Here is the commit message:
net/mlx5e: IPsec: Fix tunnel mode crypto offload for non
 TCP/UDP traffic

IPsec Tunnel mode crypto offload software parser (SWP) setting in data
path currently always set the inner L4 offset regardless of the
encapsulated L4 header type and whether it exists in the first place,
this breaks non TCP/UDP traffic as such.

Set the SWP inner L4 offset only when the IPsec tunnel encapsulated L4
header protocol is TCP/UDP.

While at it fix inner ip protocol read for setting MLX5_ETH_WQE_SWP_INNER_L4_UDP
flag to address the case where the ip header protocol is IPv6.

Fixes: f1267798c980 ("net/mlx5: Fix checksum issue of VXLAN and IPsec crypto offload")
Signed-off-by: Raed Salem <raeds@nvidia.com>
Reviewed-by: Maor Dickman <maord@nvidia.com>
Signed-off-by: Saeed Mahameed <saeedm@nvidia.com>

Here is the root cause:
The bug was caused by the software parser (SWP) always setting the inner L4 offset regardless of the encapsulated L4 header type, which led to incorrect processing of non-TCP/UDP traffic in IPsec tunnel mode. This oversight resulted in failures when handling protocols other than TCP and UDP, as the parser did not account for the absence of a valid L4 header in those cases.

Here is the patch:

 static void mlx5e_ipsec_set_swp(struct sk_buff *skb,
 				struct mlx5_wqe_eth_seg *eseg, u8 mode,
 				struct xfrm_offload *xo)
 {
 	/* Tunnel Mode:
 	 * SWP:      OutL3       InL3  InL4
 	 * Pkt: MAC  IP     ESP  IP    L4
 	 *
 	 * Transport Mode:
 	 * SWP:      OutL3       OutL4
 	 * Pkt: MAC  IP     ESP  L4
 	 *
 	 * Tunnel(VXLAN TCP/UDP) over Transport Mode
 	 * SWP:      OutL3                   InL3  InL4
 	 * Pkt: MAC  IP     ESP  UDP  VXLAN  IP    L4
 	 */

 	/* Shared settings */
 	eseg->swp_outer_l3_offset = skb_network_offset(skb) / 2;
 	if (skb->protocol == htons(ETH_P_IPV6))
 		eseg->swp_flags |= MLX5_ETH_WQE_SWP_OUTER_L3_IPV6;

 	/* Tunnel mode */
 	if (mode == XFRM_MODE_TUNNEL) {
 		eseg->swp_inner_l3_offset = skb_inner_network_offset(skb) / 2;
-		eseg->swp_inner_l4_offset = skb_inner_transport_offset(skb) / 2;
 		if (xo->proto == IPPROTO_IPV6)
 			eseg->swp_flags |= MLX5_ETH_WQE_SWP_INNER_L3_IPV6;
-		if (inner_ip_hdr(skb)->protocol == IPPROTO_UDP)
+
+		switch (xo->inner_ipproto) {
+		case IPPROTO_UDP:
 			eseg->swp_flags |= MLX5_ETH_WQE_SWP_INNER_L4_UDP;
+			fallthrough;
+		case IPPROTO_TCP:
+			/* IP | ESP | IP | [TCP | UDP] */
+			eseg->swp_inner_l4_offset = skb_inner_transport_offset(skb) / 2;
+			break;
+		default:
+			break;
+		}
 		return;
 	}

 	/* Transport mode */
 	if (mode != XFRM_MODE_TRANSPORT)
 		return;

 	if (!xo->inner_ipproto) {
 		switch (xo->proto) {
 		case IPPROTO_UDP:
 			eseg->swp_flags |= MLX5_ETH_WQE_SWP_OUTER_L4_UDP;
 			fallthrough;
 		case IPPROTO_TCP:
 			/* IP | ESP | TCP */
 			eseg->swp_outer_l4_offset = skb_inner_transport_offset(skb) / 2;
 			break;
 		default:
 			break;
 		}
 	} else {
 		/* Tunnel(VXLAN TCP/UDP) over Transport Mode */
 		switch (xo->inner_ipproto) {
 		case IPPROTO_UDP:
 			eseg->swp_flags |= MLX5_ETH_WQE_SWP_INNER_L4_UDP;
 			fallthrough;
 		case IPPROTO_TCP:
 			eseg->swp_inner_l3_offset = skb_inner_network_offset(skb) / 2;
 			eseg->swp_inner_l4_offset =
 				(skb->csum_start + skb->head - skb->data) / 2;
 			if (inner_ip_hdr(skb)->version == 6)
 				eseg->swp_flags |= MLX5_ETH_WQE_SWP_INNER_L3_IPV6;
 			break;
 		default:
 			break;
 		}
 	}

 }



